// Microsoft Sentinel (KQL): did the lab host report and alert for the test window?
let start = datetime(2026-11-05T09:00:00Z);
let finish = datetime(2026-11-05T09:15:00Z);
let host = "lab-win10-01";
union
  (SecurityEvent
    | where TimeGenerated between (start .. finish) and Computer == host and EventID == 4688
    | summarize Events = count() by Source = "process telemetry"),
  (SecurityAlert
    | where TimeGenerated between (start .. finish) and Entities has host
    | summarize Events = count() by Source = "alert: " + AlertName)
// Source                       Events
// process telemetry               212
// alert: Suspicious PowerShell      1

